<?php
require_once __DIR__.'/includes/bootstrap.php'; require_once __DIR__.'/config/db.php';
$id=filter_input(INPUT_GET,'tutor_id',FILTER_VALIDATE_INT);$reviews=[];$name='Tutor';$message='';
try{$p=db();$q=$p->prepare('SELECT u.full_name FROM tutors t JOIN users u ON u.id=t.user_id WHERE t.id=?');$q->execute([$id]);$name=$q->fetchColumn()?:$name;
if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf_token']??null)){$booking=(int)$_POST['booking_id'];$rating=max(1,min(5,(int)$_POST['rating']));$comment=trim($_POST['comment']??'');$q=$p->prepare("SELECT id FROM bookings WHERE id=? AND student_id=? AND tutor_id=? AND status='completed' AND NOT EXISTS(SELECT 1 FROM reviews WHERE booking_id=bookings.id)");$q->execute([$booking,$_SESSION['user_id']??0,$id]);if($q->fetch()){$q=$p->prepare('INSERT INTO reviews(booking_id,student_id,tutor_id,rating,comment) VALUES(?,?,?,?,?)');$q->execute([$booking,$_SESSION['user_id'],$id,$rating,$comment]);$p->prepare('UPDATE tutors SET rating=(SELECT COALESCE(AVG(rating),0) FROM reviews WHERE tutor_id=?) WHERE id=?')->execute([$id,$id]);$message='Review submitted.';}}
$q=$p->prepare('SELECT r.*,u.full_name FROM reviews r JOIN users u ON u.id=r.student_id WHERE r.tutor_id=? ORDER BY r.created_at DESC');$q->execute([$id]);$reviews=$q->fetchAll();}catch(Throwable $e){$message='Unable to load reviews.';}
$pageTitle='Reviews';require __DIR__.'/includes/header.php';require __DIR__.'/includes/navbar.php';?><main class="container py-5"><h1 class="h2">Reviews for <?=e($name)?></h1><?php if($message):?><div class="alert alert-info"><?=e($message)?></div><?php endif;?><?php if(!empty($_SESSION['user_id'])):?><details class="profile-section my-3"><summary class="fw-semibold">Write a review</summary><form method="post" class="mt-3"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input class="form-control mb-2" name="booking_id" type="number" placeholder="Completed booking ID" required><select class="form-select mb-2" name="rating"><option value="5">★★★★★</option><option value="4">★★★★</option><option value="3">★★★</option><option value="2">★★</option><option value="1">★</option></select><textarea class="form-control mb-2" name="comment" placeholder="Your experience"></textarea><button class="btn btn-brand">Submit review</button></form></details><?php endif;?><?php foreach($reviews as $r):?><article class="profile-section my-3"><strong><?=e($r['full_name'])?></strong><div class="rating"><?=str_repeat('★',(int)$r['rating'])?></div><p class="mb-0"><?=nl2br(e($r['comment']))?></p></article><?php endforeach;if(!$reviews):?><p class="text-secondary">No reviews yet.</p><?php endif;?></main><?php require __DIR__.'/includes/footer.php';?>
